morse.watch('[aria-label="Tools"]', el => {
  if (el.querySelector('[data-morse-save]')) return;
  const btn = morse.el('button', {
    'aria-label': 'Save as PNG',
    'data-morse-save': '',
    title: 'Save as PNG',
    text: '💾',
    style: 'width:38px;height:38px;margin-top:8px;border:none;background:transparent;cursor:pointer;font-size:18px;',
    on: {
      click: () => {
        const board = document.querySelector('#board');
        if (!board) return;
        board.toBlob(blob => {
          const url = URL.createObjectURL(blob);
          const a = morse.el('a', { href: url, download: 'sketch.png' });
          document.body.appendChild(a);
          a.click();
          a.remove();
          setTimeout(() => URL.revokeObjectURL(url), 1000);
        }, 'image/png');
      }
    }
  });
  el.appendChild(btn);
});

morse.watch('button[aria-label="Clear\\ canvas"]', el => {
  if (el.dataset.morseSave) return;
  el.dataset.morseSave = "1";
  const btn = morse.el('button', {
    'aria-label': 'Save PNG',
    text: 'Save PNG',
    style: 'font: inherit; padding: 4px 10px; margin-left: 6px; cursor: pointer;',
    on: {
      click: () => {
        const canvas = morse.$('#board');
        if (!canvas) return morse.toast('No drawing found');
        canvas.toBlob(blob => {
          const url = URL.createObjectURL(blob);
          const a = morse.el('a', { href: url, download: 'sketch.png' });
          document.body.appendChild(a);
          a.click();
          a.remove();
          setTimeout(() => URL.revokeObjectURL(url), 1000);
          morse.toast('Saved sketch.png');
        }, 'image/png');
      }
    }
  });
  el.insertAdjacentElement('afterend', btn);
});

(() => {
  const board = () => document.querySelector("#board");
  const savePng = () => {
    const c = board();
    if (!c) return;
    c.toBlob(blob => {
      if (!blob) return;
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = "sketch.png";
      document.body.appendChild(a);
      a.click();
      a.remove();
      setTimeout(() => URL.revokeObjectURL(url), 1000);
    }, "image/png");
  };
  morse.watch('[aria-label="Tools"]', tools => {
    if (tools.querySelector('[data-morse-save]')) return;
    const btn = morse.el("button", {
      type: "button",
      "aria-label": "Save PNG",
      "data-morse-save": "",
      title: "Save as PNG",
      text: "💾",
      style: "width:38px;height:38px;margin-top:4px;border:none;background:transparent;cursor:pointer;font-size:18px;",
      on: { click: savePng }
    });
    tools.appendChild(btn);
  });
})();

