(() => {
  const grid = () => morse.$("#__next > div:nth-of-type(2) > main > div:nth-of-type(2) > div");
  const priceOf = card => {
    const m = (card.textContent.match(/\$\s*([\d,]+(?:\.\d+)?)/) || [])[1];
    return m ? parseFloat(m.replace(/,/g, "")) : Infinity;
  };
  let sorted = false;
  const btn = morse.el("button", {
    text: "Sort by price",
    type: "button",
    "aria-label": "Sort by price: lowest first",
    style: "margin: 0 0 14px auto; padding: 6px 12px; font: inherit; font-size: 14px; color: inherit; background: transparent; border: 1px solid currentColor; border-radius: 6px; cursor: pointer; opacity: 0.85;",
    on: { click: () => {
      const g = grid();
      if (!g) return;
      const cards = Array.from(g.children);
      sorted = !sorted;
      cards.sort((a, b) => sorted ? priceOf(a) - priceOf(b) : 0);
      if (!sorted) return;
      cards.forEach(c => g.appendChild(c));
      btn.textContent = "Sort by price ✓";
    }}
  });
  morse.watch("#__next > div:nth-of-type(2) > main > div:nth-of-type(1)", el => {
    if (!el.querySelector("[data-morse-sort]")) {
      btn.setAttribute("data-morse-sort", "");
      el.appendChild(btn);
    }
  });
})();

const bar = "#__next > div:nth-of-type(2) > main > div:nth-of-type(1)";
const grid = "#__next > div:nth-of-type(2) > main > div:nth-of-type(2)";
const price = c => {
  const m = c.textContent.match(/\$([\d,]+(?:\.\d+)?)/);
  return m ? parseFloat(m[1].replace(/,/g, "")) : Infinity;
};
morse.watch(bar, el => {
  if (el.querySelector("[data-price-sort]")) return;
  el.appendChild(morse.el("button", {
    "data-price-sort": "",
    type: "button",
    style: "margin-left:auto;font:inherit;font-size:13px;padding:4px 10px;border:1px solid currentColor;border-radius:6px;background:none;color:inherit;cursor:pointer",
    text: "Sort by price: low to high",
    on: {
      click: () => {
        const g = morse.$(grid);
        if (!g) return;
        const cards = [...g.children].sort((a, b) => price(a) - price(b));
        cards.forEach(c => g.appendChild(c));
        morse.toast("Sorted by price, lowest first");
      }
    }
  }));
});

morse.watch("#__next > div:nth-of-type(2) > main > div:nth-of-type(1)", bar => {
  if (bar.querySelector("[data-sort-price]")) return;
  const btn = morse.el("button", {
    type: "button",
    text: "Sort: price, low to high",
    "data-sort-price": "",
    style: "margin-left:auto;font:inherit;font-size:14px;color:inherit;background:transparent;border:1px solid currentColor;border-radius:999px;padding:4px 12px;cursor:pointer;",
    on: { click: () => {
      const grid = morse.$("#__next > div:nth-of-type(2) > main > div:nth-of-type(2)");
      if (!grid) return;
      const priceOf = card => {
        const d = Array.from(card.querySelectorAll("div"))
          .find(x => x.children.length === 0 && /^\$\d/.test(x.textContent.trim()));
        return d ? parseFloat(d.textContent.replace(/[^0-9.]/g, "")) : Infinity;
      };
      const cards = Array.from(grid.children);
      cards.sort((a, b) => priceOf(a) - priceOf(b));
      cards.forEach(c => grid.appendChild(c));
      morse.toast("Sorted by price, low to high");
    } }
  });
  bar.appendChild(btn);
});

